    if (ob->query_skill("literate") > 99) return;

    command("pat " + ob->query("id"));
    command("say 这位" + RANK_D->query_respect(ob) + "，过来跟我学些知"
        "识(" HIY "xue zhu ziliu literate" NOR + CYN ")吧。" NOR);
}

