        me->improve_skill("dagger", 1500000);
    if (me->can_improve_skill("qingliang-daxuefa"))
        me->improve_skill("qingliang-daxuefa", 1500000);
    me->improve_skill("martial-cognize", 1500000);
    me->set("can_perform/qingliang-daxuefa/ding", 1);
    me->add("gongxian", -400);
    return 1;
}

